fn load_needle() -> String {
    let default = "ERROR".to_string();
    let path = Path::new(OVERRIDES_PATH);
    if !path.exists() {
        return default;
    }
    match fs::read_to_string(path) {
        Ok(contents) => {
            for line in contents.lines() {
                let line = line.trim();
                if let Some(value) = line.strip_prefix("needle=") {
                    return value.to_string();
                }
            }
            default
        }
        Err(_) => default,
    }
}

fn count_matching_lines(path: &str, needle: &str) -> io::Result<usize> {
    let file = fs::File::open(path)?;
    let reader = BufReader::new(file);
    let mut count = 0usize;
    for line in reader.lines() {
        let line = line?;
        if line.contains(needle) {
            count += 1;
        }
    }
    Ok(count)
}

fn main() {
    let needle = load_needle();
    match count_matching_lines(INPUT_PATH, &needle) {
        Ok(count) => println!("{}", count),
        Err(e) => {
            eprintln!("error reading {}: {}", INPUT_PATH, e);
            std::process::exit(1);
        }
    }
}

