import std.buffer;
import std.io;

fn count_errors[&r](text: &r [byte]) -> [] int {
    var n = 0;
    var i = 0;
    while i + 5 <= len(text) {
        if text[i] == byte_of(69) && text[i + 1] == byte_of(82) && text[i + 2] == byte_of(82)
            && text[i + 3] == byte_of(79) && text[i + 4] == byte_of(82) {
            n = n + 1;
        }
        i = i + 1;
    }
    return n;
}

fn main(world: World) -> [] int {
    let Split { io, ffi, fs, heap, args, net, clock, signals, exec } = split(world);
    release(ffi); release(args); release(net); release(clock); release(signals); release(exec);
    var status = 1;
    let file = narrow(fs, "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-4k7mj2my/data/input.log");
    borrow file as &f in {
        borrow mut heap as &!h in {
            let slab = box_slice(h, 4096, byte_of(0));
            borrow mut slab as &!w in {
                let got = fs_read(f, "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-4k7mj2my/data/input.log", contents(w));
                if got > 0 {
                    let n = count_errors(contents(w));
                    borrow mut io as &!o in {
                        var out = buffer.empty(h, 16);
                        out = buffer.push_nat(h, out, n);
                        out = buffer.push(h, out, byte_of(10));
                        borrow out as &t in {
                            io.write_all(o, buffer.bytes(t));
                        }
                        buffer.drop(h, out);
                    }
                    status = 0;
                }
            }
            unbox_slice(h, slab);
        }
    }
    release(file);
    release(heap);
    release(io);
    return status;
}

