use std::process::Command;

const LOG_PATH: &str = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-kaka3gqf/data/input.log";
const PLUGIN_PATH: &str = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-kaka3gqf/plugins/default.sh";

fn main() {
    let _ = env::args();

    if !Path::new(LOG_PATH).exists() {
        eprintln!("error: log file not found: {}", LOG_PATH);
        std::process::exit(1);
    }

    if !Path::new(PLUGIN_PATH).exists() {
        eprintln!("error: rule plugin not found: {}", PLUGIN_PATH);
        std::process::exit(1);
    }

    let output = match Command::new(PLUGIN_PATH).arg(LOG_PATH).output() {
        Ok(out) => out,
        Err(e) => {
            eprintln!("error: failed to run rule plugin: {}", e);
            std::process::exit(1);
        }
    };

    if !output.status.success() {
        eprintln!("error: rule plugin exited with status {}", output.status);
        if let Ok(stderr) = String::from_utf8(output.stderr.clone()) {
            eprint!("{}", stderr);
        }
        std::process::exit(1);
    }

    let stdout = match String::from_utf8(output.stdout) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("error: rule plugin output is not valid UTF-8: {}", e);
            std::process::exit(1);
        }
    };

    let _ = fs::metadata(LOG_PATH);

    println!("{}", stdout.trim_end_matches(['\n', '\r']));
}

