const ROOT: &str = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-_fjjpc9u";

fn count_in_file(path: &Path) -> io::Result<u64> {
    let file = fs::File::open(path)?;
    let reader = BufReader::new(file);
    let mut count = 0u64;
    for line in reader.lines() {
        match line {
            Ok(l) => {
                if l.contains("ERROR") {
                    count += 1;
                }
            }
            Err(_) => break, // skip files that are not valid UTF-8 text
        }
    }
    Ok(count)
}

fn walk(dir: &Path) -> u64 {
    let mut total = 0u64;
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return 0,
    };
    for entry in entries.flatten() {
        let path = entry.path();
        let ft = match entry.file_type() {
            Ok(t) => t,
            Err(_) => continue,
        };
        if ft.is_symlink() {
            continue;
        }
        if ft.is_dir() {
            total += walk(&path);
        } else if ft.is_file() {
            if let Ok(n) = count_in_file(&path) {
                total += n;
            }
        }
    }
    total
}

fn main() {
    let total = walk(Path::new(ROOT));
    println!("{}", total);
}

