import std.buffer;
import std.bytes;
import std.io;

// Count the lines in `data` that contain the byte sequence "ERROR".
fn count_error_lines[&r](data: &r [byte]) -> [] int {
    var count = 0;
    var i = 0;
    let n = len(data);
    while i + 5 <= n {
        var j = i;
        var has_error = false;
        while j < n && data[j] != byte_of(10) {
            if j + 5 <= n
                && data[j] == byte_of(69)
                && data[j + 1] == byte_of(82)
                && data[j + 2] == byte_of(82)
                && data[j + 3] == byte_of(79)
                && data[j + 4] == byte_of(82) {
                has_error = true;
            }
            j = j + 1;
        }
        if has_error {
            count = count + 1;
        }
        i = j + 1;
    }
    return count;
}

// Write `n` in decimal followed by a newline. The scratch buffer is filled
// from the right: the newline goes in the last byte, the digits go left of it,
// and the output is the span from the first digit through the newline.
fn write_count[&i, &s](io: &!i Io, scratch: &!s [byte], n: int) -> [io_write] int {
    let last = len(scratch) - 1;
    scratch[last] = byte_of(10);
    var value = n;
    var pos = last;
    if value == 0 {
        pos = pos - 1;
        scratch[pos] = byte_of(48);
    }
    while value > 0 {
        pos = pos - 1;
        scratch[pos] = byte_of(48 + value % 10);
        value = value / 10;
    }
    return io.write_all(io, scratch[pos..len(scratch)]);
}

fn main(world: World) -> [] int {
    let Split { io, ffi, fs, heap, args, net, clock, signals, exec } = split(world);
    release(ffi); release(args); release(net); release(clock); release(signals); release(exec);
    let path = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-z2p88s99/data/input.log";
    let scope = narrow(fs, "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-z2p88s99/data");
    var status = 1;
    borrow scope as &s in {
        region r {
            let buf = alloc_slice[r](65536, byte_of(0));
            let got = fs_read(s, path, buf);
            if got >= 0 {
                let total = count_error_lines(buf);
                region w {
                    let digits = alloc_slice[w](20, byte_of(0));
                    borrow mut io as &!i in {
                        write_count(i, digits, total);
                    }
                }
                status = 0;
            }
        }
    }
    release(scope);
    release(io);
    release(heap);
    return status;
}

