fn count_errors[&r](s: &r [byte]) -> [] int {
    var i = 0;
    var n = 0;
    while i + 4 < len(s) {
        if int_of(s[i]) == 69 && int_of(s[i + 1]) == 82 && int_of(s[i + 2]) == 82
            && int_of(s[i + 3]) == 79 && int_of(s[i + 4]) == 82 {
            n = n + 1;
        }
        i = i + 1;
    }
    return n;
}

fn write_count[&i](io: &!i Io, n: int) -> [io_write] int {
    region r {
        let out = alloc_slice[r](24, byte_of(0));
        var pos = 0;
        var v = n;
        if v == 0 {
            out[pos] = byte_of(48);
            pos = pos + 1;
        }
        var digits = alloc_slice[r](20, byte_of(0));
        var d = 0;
        while v > 0 {
            digits[d] = byte_of(48 + v % 10);
            v = v / 10;
            d = d + 1;
        }
        while d > 0 {
            d = d - 1;
            out[pos] = digits[d];
            pos = pos + 1;
        }
        out[pos] = byte_of(10);
        pos = pos + 1;
        return io.write_all(io, out[0..pos]);
    }
}

