    let root = Path::new(ROOT);
    let mut files = Vec::new();

    if let Err(e) = collect_files(root, &mut files) {
        eprintln!("Error walking {}: {}", root.display(), e);
    }

    let total: usize = files.iter().map(|p| count_error_lines(p)).sum();
    println!("{}", total);
}

