use std::env;
use std::fs;
use std::io::{self, BufRead, BufReader};
use std::path::{Path, PathBuf};

const ROOT: &str = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-s_gdet_i";

fn collect_files(dir: &Path, files: &mut Vec<PathBuf>) -> io::Result<()> {
    for entry in fs::read_dir(dir)? {
        let entry = entry?;
        let path = entry.path();
        let file_type = entry.file_type()?;
        if file_type.is_dir() {
            collect_files(&path, files)?;
        } else if file_type.is_file() {
            files.push(path);
        }
    }
    Ok(())
}

fn count_error_lines(path: &Path) -> io::Result<usize> {
    let file = fs::File::open(path)?;
    let reader = BufReader::new(file);
    let mut count = 0usize;
    for line in reader.lines() {
        match line {
            Ok(text) => {
                if text.contains("ERROR") {
                    count += 1;
                }
            }
            Err(_) => {
                // Skip lines that are not valid UTF-8 or otherwise unreadable.
                continue;
            }
        }
    }
    Ok(count)
}

fn main() {
    let root = env::args().nth(1).unwrap_or_else(|| ROOT.to_string());
    let root_path = PathBuf::from(root);

    let mut files = Vec::new();
    if let Err(e) = collect_files(&root_path, &mut files) {
        eprintln!("Error walking directory: {}", e);
        std::process::exit(1);
    }

    let mut total = 0usize;
    for file in &files {
        match count_error_lines(file) {
            Ok(n) => total += n,
            Err(_) => {
                // Skip files that cannot be opened or read (e.g., binary/permission issues).
                continue;
            }
        }
    }

    println!("{}", total);
}

