fn count_in_dir(dir: &Path) -> io::Result<u64> {
    let mut total: u64 = 0;
    for entry in fs::read_dir(dir)? {
        let entry = entry?;
        let path = entry.path();
        let file_type = entry.file_type()?;
        if file_type.is_dir() {
            total += count_in_dir(&path).unwrap_or(0);
        } else if file_type.is_file() {
            if let Ok(bytes) = fs::read(&path) {
                let text = String::from_utf8_lossy(&bytes);
                total += text.lines().filter(|line| line.contains("ERROR")).count() as u64;
            }
        }
    }
    Ok(total)
}

