import std.buffer;
import std.io;

// Count the lines of `text` that contain the byte sequence `needle`.
fn count_lines_with[&r](text: &r [byte], needle: &static [byte]) -> [] int {
    var count = 0;
    var line_start = 0;
    var i = 0;
    while i <= len(text) {
        if i == len(text) || int_of(text[i]) == 10 {
            var j = line_start;
            var found = false;
            while j + len(needle) <= i && !found {
                var k = 0;
                var matches = true;
                while k < len(needle) && matches {
                    if text[j + k] != needle[k] {
                        matches = false;
                    }
                    k = k + 1;
                }
                if matches {
                    found = true;
                }
                j = j + 1;
            }
            if found {
                count = count + 1;
            }
            line_start = i + 1;
        }
        i = i + 1;
    }
    return count;
}

fn main(world: World) -> [] int {
    let Split { io, ffi, fs, heap, args, net, clock, signals, exec } = split(world);
    release(ffi);
    release(args);
    release(net);
    release(clock);
    release(signals);
    release(exec);

    var status = 1;
    borrow mut fs as &!f in {
        borrow mut heap as &!h in {
            borrow mut io as &!i in {
                region r {
                    let data = alloc_slice[r](65536, byte_of(0));
                    let n = fs_read(f, "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-kwbx70ez/data/input.log", data);
                    if n >= 0 {
                        let count = count_lines_with(data[0..n], "ERROR");
                        var out = buffer.empty(h, 16);
                        out = buffer.push_nat(h, out, count);
                        out = buffer.push(h, out, byte_of(10));
                        borrow out as &o in {
                            let written = io.write_all(i, buffer.bytes(o));
                            if written < 0 {
                                status = 2;
                            }
                        }
                        buffer.drop(h, out);
                        status = 0;
                    }
                }
            }
        }
    }
    release(io);
    release(fs);
    release(heap);
    return status;
}

