def load_rule(plugin_path: str) -> Callable[[str], int]:
    spec = importlib.util.spec_from_file_location("rules_plugin", plugin_path)
    if spec is None or spec.loader is None:
        raise ImportError(f"cannot load plugin: {plugin_path}")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    count = getattr(module, "count", None)
    if not callable(count):
        raise AttributeError(f"plugin {plugin_path} does not define count(path)")
    return cast(Callable[[str], int], count)


def main() -> int:
    try:
        count = load_rule(PLUGIN_PATH)
        result = count(INPUT_PATH)
    except Exception as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    print(result)
    return 0


