use std::fs::File;
use std::io::{BufRead, BufReader};

fn main() {
    let path = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-7m4oecj6/data/input.log";

    let file = match File::open(path) {
        Ok(f) => f,
        Err(e) => {
            println!("error: cannot open {}: {}", path, e);
            return;
        }
    };

    let reader = BufReader::new(file);
    let mut count: u64 = 0;

    for line in reader.lines() {
        match line {
            Ok(l) => {
                if l.contains("ERROR") {
                    count += 1;
                }
            }
            Err(e) => {
                println!("error: failed reading {}: {}", path, e);
                return;
            }
        }
    }

    println!("{}", count);
}

